// 原死亡因果与已提供半日精确终止；失败后的全候选回滚由外层持有，非自然World战果。
#include "resident/domains/growth/growth_recovery_completion.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool value,const char* text){++checks;if(!value)throw std::runtime_error(text);}struct Injuries final:GrowthInjurySourceRead {const CommonStore& c;explicit Injuries(const CommonStore& value):c(value){}Outcome<std::vector<GrowthInjuryCause>> injury_causes(const StableId& actor,const DynamicStepInput*)const override{return {true,actor=="patient"?std::vector<GrowthInjuryCause>{{c.state().identity,actor,"military:1",1,GrowthInjuryCauseKind::military_wound,1}}:std::vector<GrowthInjuryCause>{},{}};}};
void run(bool death,bool late){auto catalog=std::make_shared<CommonCatalog>();FamilyCatalog family_catalog;FamilyState family;CommonState seed;seed.identity.world_id[0]=1;seed.identity.tick=2;seed.next_instance_id=20;catalog->places.insert("place",{"place","city",{}});RoleDefinition role;role.id="inn";role.place_id="place";catalog->roles.insert("inn",role);for(const auto* id:{"patient","provider"}){catalog->actor_ids.push_back(id);catalog->actor_initial_birth.insert(id,Integer{-14400});family_catalog.prototypes.insert(id,IdentityPrototype{});ActorRecord actor;actor.id=id;actor.alive=actor.available=true;actor.hp=100;actor.created_tick=0;actor.birth_tick=-14400;actor.location=SettlementLocation{"city","place"};actor.action_id="action:2";actor.injury=StableId{id}=="patient"?1:0;seed.actors.insert(id,actor);}ActionCoreView action{"action:2","service","patient",{"patient","provider"},2,4};seed.actions.insert(action.id,action);seed.facts.insert("military:1",{"military:1","military_casualties","military"});seed.facts.insert(action.id,{action.id,"life_activity","growth"});CommonStore c(seed,catalog);GrowthState growth;LifeActivityRecord life;life.view.fact_id=life.view.action_id=action.id;life.view.actor_id="patient";life.view.provider_actor_id="provider";life.view.kind=LifeActivityKind::service;life.view.activity="rest";life.view.start_tick=2;life.context.role_id="inn";life.context.place_id="place";ServiceTerms terms;terms.duration=4;terms.cost=20;life.terms=terms;life.cost_paid=20;growth.life_activities.insert(action.id,life);GrowthRecoveryCatalog recovery_catalog;recovery_catalog.service_roles.insert("inn",GrowthRecoveryMethod::safe_lodging);GrowthRecoveryState recovery;recovery.services.insert(action.id,{"patient","provider","inn","place",GrowthRecoveryMethod::safe_lodging,2,4,{}});GrowthSkillOriginContext origins{*catalog,family_catalog,family,nullptr};Injuries injuries(c);GrowthRecoveryHistoryAccess access{origins,injuries,[&](const StableId& actor,const DynamicStepInput*)->Outcome<std::optional<FamilyDeathOrigin>>{if(death&&actor=="provider")return {true,FamilyDeathOrigin{actor,"military:11","battle:10",3},{}};return {true,std::nullopt,{}};},[](const GrowthRecoveryService&,Integer,const StableId&){return common_success();},[](const GrowthRecoveryService&){return common_success();}};DynamicStepInput phase;phase.from_tick=2;phase.to_tick=3;phase.existing_action_ids={action.id};
if(death){c.state().actors.find("provider")->alive=false;c.state().facts.insert("battle:10",{"battle:10","military_battle","military"});c.state().facts.insert("military:11",{"military:11","military_casualties","military"});}
else{check(step_growth_recovery_service_in_candidate(c,growth,*catalog,recovery_catalog,recovery,access,action,phase).ok,"one actual provided lodging period");ActionMutation change;change.action=action;change.remaining_ticks=3;check(c.apply_action(change).ok,"original duration decremented");c.state().identity.tick=3;}
const auto saved_growth=growth;const auto saved_recovery=recovery;const auto old_id=c.state().next_instance_id;auto point=c.begin_savepoint();check(point.ok,"outer transaction owns common point");auto release=[&](const StableId& id){if(late)return common_failure("TestRecoveryReleaseLateFailure");const auto* existing=c.action(id);if(!existing)return common_failure("UnknownAction");auto old=*existing;for(const auto& person:old.participants){ActorMutation actor;actor.actor_id=person;actor.action_id=StableId{};auto changed=c.apply_actor(actor);if(!changed.ok)return changed;}ActionMutation erase;erase.kind=ActionMutation::Kind::erase;erase.action=old;return c.apply_action(erase);};
if(death){auto ended=terminate_dead_growth_recovery_services_in_candidate(c,growth,recovery_catalog,recovery,access,release,&phase);check(ended.ok!=late,"release failure is returned from actual written candidate");if(!late){check(ended.value.size()==1&&ended.value[0].provided_half_days==0&&!ended.value[0].success&&ended.value[0].code=="RecoveryProviderDied","before-actions death cannot earn a phantom period");check(!c.action(action.id),"only original release clears original action");}}
else{check(stop_growth_recovery_service_in_candidate(c,growth,recovery_catalog,recovery,access,action.id,"cancelled").ok,"buyer cancels actual service");const auto closed=recovery.closures.order().back();auto result=read_growth_recovery_completion(c,growth,recovery,closed);check(result.ok&&!result.value.success&&result.value.provided_half_days==1&&result.value.code=="RecoveryCancelled","cancel keeps exactly provided points");check(!read_growth_recovery_completion(c,growth,recovery,"action:2").ok,"missing action is not completion");}
if(late){check(c.rollback_savepoint(point.value).ok,"outer rollback remains available");growth=saved_growth;recovery=saved_recovery;check(c.state().next_instance_id==old_id&&recovery.closures.empty()&&growth.life_activities.find(action.id)->view.phase==LifeActivityPhase::active&&c.action(action.id),"Common ID, original life and recovery all restored");}else check(c.commit_savepoint(point.value).ok,"outer owner commits one candidate");}}
int main(){try{run(false,false);run(true,false);run(true,true);std::cout<<"GROWTH_RECOVERY_COMPLETION "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
